import sys,json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]));sys.path.insert(0,str(Path(__file__).resolve().parent))
from gongbi_training.runtime import configure,LAB
configure()
import numpy as np,torch
from PIL import Image,ImageDraw,ImageFont
from guohua_objects_v4_20261116 import ROOT,OLD,REF,ARMS,ALL,read,write,sha,checks
from guohua_objects_train_20261112 import confusion
COLORS=np.array([[145,157,170],[183,134,75],[65,149,91]],'uint8');NAMES=['上轮扩充模型','同条件对照','稀疏弱监督']
def main():
 ds=read(ROOT/'dataset_manifest.json');res=read(ROOT/'results.json');p=res['protocol'];refs=read(REF/'reviewed_references.json');assert sha(REF/'reviewed_references.json')==p['reference_sha256'];assert sha(ROOT/'dataset_manifest.json')==p['dataset_sha256'];assert sha(Path(__file__).with_name('guohua_objects_v4_20261116.py'))==p['script_sha256'];assert sha(OLD/'results.json')==p['old_result_sha256'];assert sha(OLD/'expanded_control.pt')==p['initial_sha256'];assert sha(Path(__file__).resolve().parents[1]/'gongbi_training/sparse_object_supervision.py')==p['loss_module_sha256'];(ROOT/'views').mkdir(exist_ok=True)
 initial=torch.load(OLD/'expanded_control.pt',map_location='cpu',weights_only=False)['model']
 for a,h in res['checkpoint_hashes'].items():
  assert sha(ROOT/(a+'.pt'))==h;state=torch.load(ROOT/(a+'.pt'),map_location='cpu',weights_only=False)['model'];assert all(torch.equal(v,state[k]) for k,v in initial.items() if k.startswith('encoder.'))
 byid={r['id']:r for r in ds['records']};records=[]
 ids=['H_14']+[r['id'] for r in res['records'] if r['split'] in ['new_test','old_named_regression','train']]
 for ident in ids:
  if ident=='H_14':image=LAB/'cunfa_roles_v2_20261112/references/H_14_input.png';t=None;split='known_user_regression'
  else:image=byid[ident]['image'];t=np.array(Image.open(byid[ident]['target']));split=byid[ident]['split'];assert sha(image)==byid[ident]['image_sha256']
  im=Image.open(image).convert('RGB');im.save(ROOT/'views'/(ident+'_input.png'));paths={}
  for a in ALL:
   z=np.load(ROOT/'predictions'/(ident+'_'+a+'.npz'));Image.fromarray(COLORS[z['prediction']]).save(ROOT/'views'/(ident+'_'+a+'.png'));paths[a]='views/'+ident+'_'+a+'.png'
   if t is not None:assert confusion(t,z['prediction']).tolist()==next(r for r in res['records'] if r['id']==ident)['scores'][a]['confusion']
  records.append(dict(id=ident,split=split,input='views/'+ident+'_input.png',predictions=paths))
 diagnostic=[]
 for c in refs['cases']:
  per=[]
  for r in c['regions']:
   if r['kind']!='core_polygon' or r['object']=='unknown':continue
   mask=Image.new('L',tuple(c['size']),0);ImageDraw.Draw(mask).polygon([tuple(x) for x in r['points']],fill=255);m=np.array(mask)>0;expected=1 if r['object']=='rock' else 2
   per.append(dict(region=r['name'],object=r['object'],scores={a:float((np.load(ROOT/'predictions'/(c['id']+'_'+a+'.npz'))['prediction'][m]==expected).mean()) for a in ALL}))
  diagnostic.append(dict(id=c['id'],use='known_case_not_training' if c['id']=='H_14' else 'weak_training_reference_in_sample',regions=per))
 write('report_data.json',dict(records=records,aggregates=res['aggregates'],user=res['user_foliage_recall'],sparse_diagnostic=diagnostic))
 def board(rows,name):
  b=Image.new('RGB',(1440,len(rows)*350+65),'#f4f1e8');d=ImageDraw.Draw(b);font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18)
  for i,r in enumerate(rows):
   for j,(path,title) in enumerate(zip([r['input']]+[r['predictions'][a] for a in ALL],['原图']+NAMES)):
    im=Image.open(ROOT/path);im.thumbnail((346,280));b.paste(im,(j*360+6,i*350+35));d.text((j*360+6,i*350+5),title,font=font,fill='#294735')
   d.text((6,i*350+320),r['id'],font=font,fill='#79523a')
  d.text((6,len(rows)*350+4),'棕=山石，绿=树木，灰蓝=其他；直接对象预测，非墨带、线稿或皴法复刻。',font=font,fill='#79523a');b.save(ROOT/name,quality=94)
 board(records[:1],'foliage_regression.jpg');worst=sorted([r for r in res['records'] if r['split']=='new_test'],key=lambda r:r['scores']['sparse_weak']['mean_iou'])[:3];board([next(r for r in records if r['id']==w['id']) for w in worst],'new_test_failures.jpg')
 resultchecks=checks();resultchecks.update(protocol_checkpoint_reference_hashes_match=True,old_model_unchanged=True,encoders_frozen=True,raw_metrics_recomputed=True,H_14_not_training=True,unknown_and_corridors_not_weak_labels=True,reference_regions=13,independent_test=False,model_adopted=False,robot_connected=False);write('verification.json',resultchecks)
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>稀疏对象弱监督对照</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#294735;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:29px}.note{padding:15px;background:#fff8e8;border-left:5px solid #b47a42}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{min-width:0;background:#fffdf8;padding:10px;border:1px solid #d5d9cd}img{display:block;max-width:100%;height:auto;margin:auto}select{max-width:100%;width:650px;padding:8px;font:inherit}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #d1d6ca}.warn{color:#8b5035}a{color:#236b61}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:24px}}</style><main><small>2026-11-16 · 离线弱监督试训 · 未替换绘画版本</small><h1>13处对象内部弱参考，是否带来可复现改善</h1><p class="note" id="headline"></p><p>从同一个上轮扩充模型开始，两组均固定192步、相同采样与增强、学习率0.0001、冻结编码器。同条件对照与候选都对明确待定区及稀疏参考区关闭原粗标签损失，并在其余已标区域增加0.2倍旧模型保持损失；候选额外增加0.25倍稀疏对象损失。本轮对照是这一共同基础上的消融，不是未经修改的普通续训。</p><p>每批一张来自三张弱参考训练图，其余按作品组采样。两组图像曝光相同。只有13个内部区域进入候选弱监督；轮廓附近走廊不进入，明确未知处不作背景，H_14没有进入训练。这13处仍是助手参考，不是专家真值或真实墨迹标签。</p><h2>1. 已知树叶案例</h2><img src="foliage_regression.jpg"><p id="foliage"></p><p>此处使用原有1,647像素核心检查，非新盲测、非精确叶片墨带。另列较小的助手参考区域，与原核心分母不同，不混用。</p><h2>2. 同一批已知作品回归</h2><div class="scroll"><table><thead><tr><th>范围</th><th>方法</th><th>平均IoU</th><th>山石IoU</th><th>树木IoU</th><th>树→石</th><th>石→树</th></tr></thead><tbody id="metrics"></tbody></table></div><p class="warn">原14图已反复查看，只是已知作品回归。旧12图也只来自1个作品候选组。没有新专家准确率或独立验收结论。指标只统计源粗对象标注，不代表皴法辨识、淡线恢复、完整笔画质量或实画。未按回归结果选择检查点或调整权重。</p><h2>3. 逐张直接输出</h2><select id="case"></select><p id="scope"></p><div class="grid"><div class="card"><b>原图</b><img id="input"></div><div class="card"><b>上轮扩充模型</b><img id="previous"></div><div class="card"><b>同条件对照</b><img id="matched_control"></div><div class="card"><b>稀疏弱监督</b><img id="sparse_weak"></div></div><p id="refnote">本页无完整对象边界真值。棕=山石，绿=树木，灰蓝=其他；对象区域不是墨迹，空白未标处也可能误分。预测未经参考遮罩改色。</p><h2>4. 稀疏参考的逐处诊断</h2><div class="scroll"><table><thead><tr><th>案例与用途</th><th>助手参考区域</th><th>上轮</th><th>同条件对照</th><th>弱监督</th></tr></thead><tbody id="local"></tbody></table></div><p>三张已用于训练的参考图属于样本内拟合检查，不能证明泛化；H_14仅作已知错例。比例表示模型类别与所选对象区域的对应程度，不是专家准确率。未知与走廊不计入该表。</p><h2>5. 最低分回归案例</h2><img src="new_test_failures.jpg"><p>显示弱监督候选在已知14图中平均IoU最低的三例，没有据此重训或改阈值。</p><h2>6. 阶段状态</h2><p>尚未通过对象或皴法独立验收，树木画法训练保持关闭。没有训练新皴法分类器或完整笔触模型，没有连接机械臂。本轮仅验证小规模对象弱监督，不把训练区域改善当作整体能力提升。后续仍需独立作品、可靠对象边界及真实墨带参考。</p><p><a href="protocol.json">冻结训练协议</a> · <a href="weak_reference_manifest.json">使用与排除的弱参考</a> · <a href="results.json">原始结果</a> · <a href="verification.json">检查记录</a></p></main><script>let D;const A=['previous','matched_control','sparse_weak'],N=['上轮扩充模型','同条件对照','稀疏弱监督'],$=s=>document.getElementById(s),pct=x=>x===null?'无参考':(x*100).toFixed(1)+'%';function show(){let r=D.records[$('case').selectedIndex];$('input').src=r.input;for(let a of A)$(a).src=r.predictions[a];$('scope').textContent=r.id+' / '+r.split}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of d.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').onchange=show;show();let q=d.aggregates.new_test;$('headline').textContent='已知14图平均IoU：'+A.map((a,i)=>N[i]+' '+pct(q[a].mean_iou)).join('；')+'。单看总分不够，需同时检查双向误判、树叶核心及样本内拟合；本轮不自动替换版本。';$('foliage').textContent='原有树叶核心召回：'+A.map((a,i)=>N[i]+' '+pct(d.user[a])).join('；');for(let [s,t] of [['new_test','已知14图／4作品候选组'],['old_named_regression','旧12图／1作品候选组']])for(let [i,a] of A.entries()){let v=d.aggregates[s][a],tr=document.createElement('tr');tr.innerHTML='<td>'+t+'</td><td>'+N[i]+'</td>'+[v.mean_iou,v.iou[1],v.iou[2],v.tree_as_rock_rate,v.rock_as_tree_rate].map(x=>'<td>'+pct(x)+'</td>').join('');$('metrics').append(tr)}for(let c of d.sparse_diagnostic)for(let r of c.regions){let tr=document.createElement('tr');tr.innerHTML='<td>'+c.id+' / '+c.use+'</td><td>'+r.region+' / '+r.object+'</td>'+A.map(a=>'<td>'+pct(r.scores[a])+'</td>').join('');$('local').append(tr)}window.reportReady=true});</script></html>'''
 page=page.replace('<h1>13处对象内部弱参考，是否带来可复现改善</h1>','<h1>树叶保护恢复，整体回归仍未超过旧版</h1><p class="note"><b>本轮仍不采用新模型。</b>已知14图：旧版70.6%，同条件对照68.2%，弱监督67.9%。原有树叶核心召回：旧版94.0%，对照99.5%，弱监督100.0%。两组都恢复树叶，尚不能归功于弱标签；单例改善也不能抵消整体回归退步。</p>')
 (ROOT/'index.html').write_text(page,encoding='utf8')
 source=Path(__file__).with_name('serve_guohua_objects_v2_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_objects_v4_sparse_20261116');start=source.index('ALLOWED={');end=source.index('\nALLOWED.update',start);source=source[:start]+"ALLOWED={'index.html','foliage_regression.jpg','new_test_failures.jpg','report_data.json','protocol.json','results.json','verification.json','weak_reference_manifest.json'}"+source[end:];(ROOT/'serve_report.py').write_text(source.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8')
 checker=Path(__file__).with_name('check_guohua_objects_v2_view_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_objects_v4_sparse_20261116').replace(')==27',')==30').replace('range(27)','range(30)').replace(';assert js("document.querySelectorAll(\'#works tr\').length")==4','').replace('work_metrics_four_rows=True,','').replace('all27_observations_switch_and_load','all30_observations_switch_and_load').replace("['protocol.json','results.json','selection_before_download.json','source_checked_cunfa_concepts.json','verification.json']","['protocol.json','results.json','weak_reference_manifest.json','verification.json']").replace("'expanded_control.pt','line_aware_aug.pt','../expanded_control.pt','predictions/H_14_expanded_control.npz'","'matched_control.pt','sparse_weak.pt','../sparse_weak.pt','predictions/H_14_sparse_weak.npz'")
 checker=checker.replace("assert requests.post(url,timeout=5).status_code==405","assert js('document.querySelectorAll(\"#local tr\").length')==17\n assert requests.post(url,timeout=5).status_code==405")
 (ROOT/'check_report.py').write_text(checker.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8');print(json.dumps(resultchecks),flush=True)
if __name__=='__main__':main()
